// Xmuse board status mod — PluginState contract.
//
// This file is the one place the shapes the pane reads are written. It is
// self-contained (no imports) and is named in plugin.json as "types".
// Every value below is structured server data only: counts, state codes,
// module ids, reason codes. Agent-authored text is kept out of the status
// line / toast / command / tool paths by construction (see src/text.ts);
// the pane holds a bounded, sanitized copy for the expanded detail only.

export type XmuseAttentionItem = {
  kind: string;
  reason_code: string;
  module_id: string | null;
  split_id: string | null;
  integration_id: string | null;
};

export type XmuseIntegrationState = {
  status: string | null;
  green_head_commit: string | null;
};

export type XmuseModuleIntegration = {
  status: string;
  verification_id: string | null;
  integrated_verification_id: string | null;
  conflict_path_count: number;
  reason_code: string | null;
};

export type XmuseSummary = {
  conversation_id: string;
  revision: string;
  board_seq: number;
  modules_total: number;
  counts: { [state: string]: number };
  attention: XmuseAttentionItem[];
  attention_total: number;
  // Accepted modules (§4.4). Equals counts.verified while reviews are off.
  accepted_total: number;
  // capabilities.reviews from the projection/summary: 1 while cross-family
  // reviews are on, 0 otherwise (old servers: 0).
  reviews: number;
  // capabilities.integrations (§3.11): 1 while the host integrates, 0
  // otherwise (old servers: 0). Gates every integration word.
  integrations: number;
  // Accepted modules integrated at their current verification (§3.11).
  // Default 0 on old servers.
  integrated_total: number;
  // Room-level job state (§3.11, §7.1): latest status (null when none or
  // integrated) is shown as a job word; the green head is shortened.
  // Never a path, never a job id.
  integration: XmuseIntegrationState;
};

export type XmuseAgentSnippet = {
  field: string;
  text: string;
};

// Structured review state of one module. Counts only: the mod never
// reads review summaries or finding text (no AgentText leaves here).
export type XmuseReviewInfo = {
  status: string;
  // Opaque id and digest guard, used only for a Human decision under a
  // grant (main_window_control_v1 §4.4); never shown in a label or toast.
  review_id: string | null;
  digest: string | null;
  reviewer_kind: string | null;
  escalated_from_present: boolean;
  findings_count: { blocker: number; major: number; minor: number };
};

export type XmuseModule = {
  module_id: string;
  state: string;
  lifecycle: string;
  owner_display: string;
  provider_kind: string;
  done_reports: number;
  passed: number;
  failed: number;
  rework_rounds: number;
  gate_ids: string[];
  stale_contracts: string[];
  attention_kind: string;
  attention_reason: string | null;
  charter_version: number;
  paths: string[];
  provides: string[];
  depends: string[];
  // The one completion value (§4.4). Missing on old servers: false.
  accepted: boolean;
  review: XmuseReviewInfo;
  // Per-module integration state (§3.11). The none values when the module
  // has no candidate or the server predates integrations.
  integration: XmuseModuleIntegration;
};

export type XmuseModuleDetail = {
  module_id: string;
  snippets: XmuseAgentSnippet[];
};

export type XmuseBoard = {
  revision: string;
  modules: XmuseModule[];
  details: XmuseModuleDetail[];
  contracts: { contract_id: string; latest_version: number }[];
  proposed_splits: string[];
  splits: XmuseSplitSummary[];
  operator_attention: XmuseAttentionItem[];
  // capabilities.reviews of the projection (1 while reviews are on).
  reviews: number;
  // Modules with accepted == true in this projection.
  accepted_total: number;
  // capabilities.integrations of the projection (1 while integrating).
  integrations: number;
  // Modules accepted and integrated at their current verification.
  integrated_total: number;
  // Room-level job state (§3.11): latest status plus the green head.
  integration: XmuseIntegrationState;
};

// One split row the pane may offer a decision on. Only structured fields:
// status codes and the digest guard. Module titles and path globs stay in
// the expanded module detail and never enter a control label or a toast.
export type XmuseSplitSummary = {
  split_id: string;
  status: string;
  digest: string;
};

// Non-secret grant metadata the pane renders from (plugin_grant/v2). The
// token itself lives only in a module-level variable of the hooks module,
// never here.
export type XmuseGrantMeta = {
  grantId: string;
  expiresAt: string;
  conversationIds: string[];
  scopes: string[];
};

// A pending two-step decision. kind "split": splitId + decision.
// kind "review": reviewId + decision (endorse|object); an objection first
// collects the human's reason (reason null until entered), then the digest.
export type XmuseConfirming = {
  kind: string;
  splitId: string;
  reviewId: string;
  decision: string;
  reason: string | null;
};

// Review material fetched under a grant, drawn only in the pane (§4.5).
// The patch is agent-authored: sanitized, truncated and labelled untrusted.
export type XmuseReviewMaterial = {
  reviewId: string;
  digest: string;
  text: string;
  truncated: boolean;
};

export type XmuseCache = {
  binding: string | null;
  cwd: string | null;
  summary: XmuseSummary | null;
  board: XmuseBoard | null;
  summaryEtag: string | null;
  boardEtag: string | null;
  lastPollAt: number | null;
  offline: boolean;
  baselined: boolean;
  seenAttention: string[];
  seenStates: { [module_id: string]: string };
  failCount: number;
  nextRetryAt: number;
  paneOpen: boolean;
  expanded: { [module_id: string]: boolean };
  grant: XmuseGrantMeta | null;
  confirming: XmuseConfirming | null;
  material: XmuseReviewMaterial | null;
  formEpoch: number;
};

declare module "claude-code" {
  interface PluginState {
    xmuse: { cache: XmuseCache };
  }
}
